; -----------------------------------------------------------------------------
; $F4 raw-text bank selector helper.
; Entry: A is the shifted packed-bank word produced by the native pointer decoder.
; Exit:  $24 contains the ordinary resolved bank, except $F2 becomes $F3 when
;        ($7E22E9 & $10) != 0. Other banks pass through exactly.
; Clobbers A/flags only, matching the native raw-pointer tail.
org $F40000
V104_SelectRawTextBank:
    db $EB                         ; XBA
    db $29, $FF, $00              ; AND #$00FF
    db $18                         ; CLC
    db $69, $C0, $00              ; ADC #$00C0
    db $C9, $F2, $00              ; CMP #$00F2
    db $D0, $0F                   ; BNE .store
    db $48                         ; PHA
    db $AF, $E9, $22, $7E         ; LDA.l $7E22E9
    db $29, $10, $00              ; AND #$0010
    db $F0, $04                   ; BEQ .normal
    db $68                         ; PLA
    db $1A                         ; INC A ($F2 -> $F3)
    db $80, $01                   ; BRA .store
    db $68                         ; .normal: PLA
    db $85, $24                   ; .store: STA $24
    db $6B                         ; RTL


