org $F00013
V106_P1_ABSwap_Hook:
    db $20, $50, $02              ; JSR $F0:0250
org $F0002F
V106_P2_ABSwap_Hook:
    db $20, $55, $02              ; JSR $F0:0255

; --- Ring input helper refinements ----------------------------------------------
; FuSoYa's original directional ring-input dispatcher is preserved byte-for-byte.
org $F00300
V106_RingDirectionDispatcher_Restored:
    db $20, $22, $09              ; JSR $F0:0922 (v1.05 original)

; FuSoYa's ring Cancel helper originally masks Y ($4000). After the A/B swap,
; physical B appears as logical A ($0080). Also accept Start ($1000).
org $F00343
