    db $29, $80, $10              ; AND #$1080

; The central ring input selector returns P2 input at $F0:0962 when the current
; ring belongs to a P2-owned actor. Redirect only that return through a tiny helper
; that substitutes P1 input while our transient forced-P1 flag is active.
org $F00962
V106_RingP2Return_Hook:
    db $4C, $28, $03              ; JMP $F0:0328

