    db $54, $01, $55, $44, $00, $02, $02, $14, $08, $00

; --- Dispatcher teardown correction ------------------------------------------
; Expected Phase-2 bytes at both sites: JSR $690F (clear selected/current slot).
; Replace with JSR $691D, the already-proven clear-both routine used by $52.
org $F76B00
    db $20, $1D, $69
org $F76B47
